import{_ as t,o as a,c as e,ae as o}from"./chunks/framework.RRduUuAx.js";const _=JSON.parse('{"title":"iCost 帳單匯入指南","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/guide/08-icost-bill-import-guide.md","filePath":"v1/zh-HK/guide/08-icost-bill-import-guide.md"}'),l={name:"v1/zh-HK/guide/08-icost-bill-import-guide.md"};function r(s,i,c,d,n,h){return a(),e("div",null,[...i[0]||(i[0]=[o('<h1 id="icost-帳單匯入指南" tabindex="-1">iCost 帳單匯入指南 <a class="header-anchor" href="#icost-帳單匯入指南" aria-label="Permalink to &quot;iCost 帳單匯入指南&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>考拉記帳支援匯入 iCost 匯出的 Excel 檔（<code>.xlsx</code> / <code>.xls</code>），不支援 iCost 的 CSV。</p><h2 id="📤-在-icost-匯出-簡要" tabindex="-1">📤 在 iCost 匯出（簡要） <a class="header-anchor" href="#📤-在-icost-匯出-簡要" aria-label="Permalink to &quot;📤 在 iCost 匯出（簡要）&quot;">​</a></h2><p>在 iCost 的設定/更多中找到「匯出/資料匯出/匯出帳單」，選擇匯出格式為 <strong>Excel</strong> 後保存到本機。</p><h2 id="📥-在考拉記帳匯入" tabindex="-1">📥 在考拉記帳匯入 <a class="header-anchor" href="#📥-在考拉記帳匯入" aria-label="Permalink to &quot;📥 在考拉記帳匯入&quot;">​</a></h2><ol><li>設定 → 帳單匯入</li><li>匯入來源選「iCost」</li><li>選擇 Excel 檔案</li><li>關聯帳本 → 解析 → 預覽 → 匯入</li></ol><h2 id="⚠️-注意事項" tabindex="-1">⚠️ 注意事項 <a class="header-anchor" href="#⚠️-注意事項" aria-label="Permalink to &quot;⚠️ 注意事項&quot;">​</a></h2><ul><li>解析會依賴表頭行包含「日期」。若 iCost 可選語言，建議以中文表頭匯出。</li><li>重複匯入同一份檔案可能產生重複帳單，請避免。</li></ul><hr><p><strong>最後更新</strong>：2026 年 4 月</p>',11)])])}const p=t(l,[["render",r]]);export{_ as __pageData,p as default};
